<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<section class="admin-page-heading"><div><p class="eyebrow">Publishing</p><h1>News</h1><p>Create, publish, keep editing, archive, or restore news from one place.</p></div><?php if($canCreate):?><a class="button button-primary" href="<?=View::escape($baseUrl)?>admin/news/create">Create news</a><?php endif;?></section>
<section class="admin-card"><div class="table-wrap"><table><thead><tr><th>Article</th><th>Date</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if($items===[]):?><tr><td colspan="4">No news items yet.</td></tr><?php endif;?><?php foreach($items as$i):?><tr><td><strong><?=View::escape($i['title'])?></strong><br><small><?=View::escape($i['category_name'])?></small></td><td><?=View::escape($i['article_date'])?></td><td><span class="status-badge"><?=View::escape($i['status'])?></span></td><td><div class="table-actions"><?php if($canEdit):?><a href="<?=View::escape($baseUrl)?>admin/news/<?=(int)$i['id']?>/edit">Edit</a><?php endif;?><?php $action=$i['status']==='published'?'archive':($i['status']==='archived'?'restore':'publish');$allowed=$action!=='publish'||$canPublish;if($allowed):?><form method="post" action="<?=View::escape($baseUrl)?>admin/news/<?=(int)$i['id']?>/workflow"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button class="link-button" name="action" value="<?=$action?>"><?=ucfirst($action)?></button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section>
